using GraphApi.Models.VTS.TipoIdentificacion;namespace GraphApi.Services.VTS.TipoIdentificacion{    /// <summary>    /// Define las operaciones de negocio y persistencia para TipoIdentificacions.    /// </summary>    public interface ITipoIdentificacionService    {        /// <summary>        /// Obtiene la lista de TipoIdentificacions con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTipoIdentificacion>> GetTipoIdentificacions(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TipoIdentificacions con filtros opcionales.        /// </summary>        /// <param name="tipoIdentificacionID">Filtro opcional para TipoIdentificacionID.</param>        /// <param name="tipoIdentificacion">Filtro opcional para TipoIdentificacion.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTipoIdentificacionsDynamic(            int? tipoIdentificacionID,            string? tipoIdentificacion,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TipoIdentificacion.        /// </summary>        /// <param name="objInput">Datos para crear el TipoIdentificacion.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTipoIdentificacion> CreateTipoIdentificacion(            clCreateTipoIdentificacion objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TipoIdentificacion.        /// </summary>        /// <param name="objInput">Datos para actualizar el TipoIdentificacion, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTipoIdentificacion?> UpdateTipoIdentificacion(            clUpdateTipoIdentificacion objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TipoIdentificacion por su ID.        /// </summary>        /// <param name="nTipoIdentificacionID">ID del TipoIdentificacion a eliminar.</param>        Task<bool> DeleteTipoIdentificacion(int nTipoIdentificacionID);    }}